#include "tigersheets/ooxml.hpp"
#include <pugixml.hpp>
#include <zip.h>
#include <filesystem>
#include <sstream>
#include <iostream>
#include <stdexcept>
#include <unistd.h>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){const auto path=(std::filesystem::temp_directory_path()/("tigersheets-row-descent-"+std::to_string(getpid())+".xlsx")).string();const auto output=path+"-saved.xlsx";try{
 auto book=WorkbookSession().snapshot();book["sheets"][0]["cells"]=Json::array({{{"row",4},{"col",2},{"input","First"}},{{"row",9},{"col",2},{"input","Second"}}});writeWorkbook(path,book);auto package=readWorkbook(path);pugi::xml_document doc;require(doc.load_string(package.entries.at("xl/worksheets/sheet1.xml").c_str()),"fixture XML");auto root=doc.document_element();root.append_attribute("xmlns:x14ac")="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac";for(auto row:root.child("sheetData").children())row.append_attribute("x14ac:dyDescent")=row.attribute("r").as_int()==4?0.25:0.5;auto cols=root.insert_child_before("cols",root.child("sheetData"));for(int column:{2,3}){auto col=cols.append_child("col");col.append_attribute("min")=column;col.append_attribute("max")=column;col.append_attribute("width")=15.0;col.append_attribute("customWidth")=1;col.append_attribute("bestFit")=column==2;}std::ostringstream xml;doc.save(xml);const auto text=xml.str();int error=0;auto* archive=zip_open(path.c_str(),0,&error);require(archive,"fixture ZIP");auto* source=zip_source_buffer(archive,text.data(),text.size(),0);require(source&&zip_file_add(archive,"xl/worksheets/sheet1.xml",source,ZIP_FL_OVERWRITE)>=0&&zip_close(archive)==0,"fixture member");package=readWorkbook(path);const auto id=package.workbook.at("sheets")[0].at("id").get<std::string>();preflightWorksheetStructure(package,id);WorkbookSession session(package.workbook);const auto baseline=session.snapshot();require(session.apply(0,Json::array({{{"type","insert_rows"},{"sheet",id},{"index",4},{"count",2}}})),"insert through native row descent");require(session.apply(session.snapshotView().at("revision"),Json::array({{{"type","insert_columns"},{"sheet",id},{"index",2},{"count",1}}})),"insert columns through native AutoFit metadata");writeWorkbook(output,session.snapshot(),&package);auto reopened=readWorkbook(output);pugi::xml_document saved;require(saved.load_string(reopened.entries.at("xl/worksheets/sheet1.xml").c_str()),"saved XML");int count=0;for(auto row:saved.document_element().child("sheetData").children())if(auto attr=row.attribute("x14ac:dyDescent")){const int index=row.attribute("r").as_int();require((index==6&&attr.as_double()==0.25)||(index==11&&attr.as_double()==0.5),"native row baseline metadata moves with its original row");++count;}require(count==2,"both native row baseline records persist with no stale coordinates");int fitted=0;for(auto col:saved.document_element().child("cols").children())if(auto attr=col.attribute("bestFit")){const int index=col.attribute("min").as_int();require((index==3&&attr.as_bool())||(index==4&&!attr.as_bool()),"native AutoFit flag follows its original column including explicit false");++fitted;}require(fitted==2,"native AutoFit flags persist without stale indexes");require(session.undo()&&session.undo()&&session.snapshotView().at("sheets")==baseline.at("sheets"),"row baseline metadata restores with the structural Undo");std::filesystem::remove(path);std::filesystem::remove(output);std::cout<<"Native row descent metadata passed\n";
 }catch(const std::exception& error){std::filesystem::remove(path);std::filesystem::remove(output);std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
